function validate(input) {
  const [{ Drivers = [], Rides = [], AcceptedRides = [] }] = input;
  const date = /^\d{4}-\d{2}-\d{2}$/;
  const joined = new Map(), requested = new Map(), accepted = new Set();
  for (const [id, day] of Drivers) {
    if (id === null || day === null) return 'Every driver needs a driver_id and a join_date.';
    if (!date.test(day)) return `join_date ${day} is not YYYY-MM-DD.`;
    if (joined.has(id)) return `driver_id ${id} appears twice in Drivers.`;
    joined.set(id, day);
  }
  for (const [id, user, day] of Rides) {
    if (id === null || user === null || day === null) return 'Every ride needs a ride_id, a user_id and a requested_at.';
    if (!date.test(day)) return `requested_at ${day} is not YYYY-MM-DD.`;
    if (requested.has(id)) return `ride_id ${id} appears twice in Rides.`;
    requested.set(id, day);
  }
  for (const [ride, driver] of AcceptedRides) {
    if (ride === null || driver === null) return 'Every accepted ride needs a ride_id and a driver_id.';
    if (accepted.has(ride)) return `ride_id ${ride} appears twice in AcceptedRides.`;
    accepted.add(ride);
    if (!requested.has(ride)) return `Accepted ride ${ride} is not in Rides.`;
    if (!joined.has(driver)) return `Driver ${driver} is not in Drivers.`;
    if (joined.get(driver) > requested.get(ride)) return `Driver ${driver} accepts ride ${ride} before joining.`;
  }
  return null;
}

