function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const dayText = offset => new Date(Date.UTC(2019, 9, 1) + offset * 86400000).toISOString().slice(0, 10);
  // Small cases favour month boundaries and the edges of 2020; large ones spread over Oct 2019 to Mar 2021.
  const edges = ['2019-11-15', '2019-12-31', '2020-01-01', '2020-01-31', '2020-02-01', '2020-02-29', '2020-03-31',
    '2020-04-01', '2020-06-15', '2020-07-31', '2020-08-01', '2020-10-24', '2020-11-30', '2020-12-01', '2020-12-31', '2021-01-01', '2021-01-15'];
  const randomDay = () => small ? pick(edges) : dayText(Math.floor(rand() * 540));
  const driverCount = small ? Math.floor(rand() * 7) : 300;
  const rideCount = small ? Math.floor(rand() * 9) : 2000;
  const Drivers = [], Rides = [], AcceptedRides = [];
  const driverIds = Array.from({ length: driverCount + 3 }, (_, i) => i + 1);
  for (let i = driverIds.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [driverIds[i], driverIds[j]] = [driverIds[j], driverIds[i]]; }
  for (let i = 0; i < driverCount; i++) Drivers.push([driverIds[i], randomDay()]);
  for (let id = 1; id <= rideCount; id++) {
    const day = randomDay();
    Rides.push([id, 1 + Math.floor(rand() * (small ? 5 : 200)), day]);
    if (rand() < (small ? 0.75 : 0.5)) {
      const eligible = Drivers.filter(([, joined]) => joined <= day);
      // A few drivers take most rides, so a driver often accepts several rides in one month.
      if (eligible.length) {
        const driver = rand() < 0.5 ? eligible[0][0] : pick(eligible)[0];
        AcceptedRides.push([id, driver, 1 + Math.floor(rand() * 120), 1 + Math.floor(rand() * 110)]);
      }
    }
  }
  for (let i = Rides.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Rides[i], Rides[j]] = [Rides[j], Rides[i]]; }
  return [{ Drivers, Rides, AcceptedRides }];
}
